def frequency_check(dictionary):
	for item in range(len(dictionary.keys()) - 1):
		if dictionary.keys()[item] != dictionary.keys()[item + 1]:
			return False
	return True

def max_key(dictionary):
	Max = 0
	for item in dictionary:
		if dictionary[item] > Max:
			Max = dictionary[item]
	return Max

def func():
	n = int(input())
	arr = list(map(int, input().split()))
	if n <= 2:
		return 0
	empt = {}
	for i in range(n):
		if arr[i] not in empt:
			empt[arr[i]] = 1
		else:
			empt[arr[i]] += 1
	if max_key(empt) == 1:
		return n - 2
	return n - max_key(empt)
t = int(input())
while t != 0:
	t = t - 1
	print(func())
